/**
 * SW Template — Workbox injects the precache manifest at build time.
 * The manifest is also written to /precache-manifest.json for runtime consumption.
 *
 * On install, the SW reads precache-manifest.json and populates the precache.
 * Static build assets are served cache-first from the precache.
 *
 * DO NOT EDIT THIS FILE DIRECTLY for production changes.
 * The generated file is public/sw.js (output of scripts/generate-sw.js).
 *
 * To modify caching behavior, edit this template and re-run the build.
 */

// ═══════════════════════════════════════════════════════════════════════════
// Constants
// ═══════════════════════════════════════════════════════════════════════════
const CACHE_NAMES = {
  precache: 'lmr-precache-v1',
  static: 'lmr-static-v1',
  images: 'lmr-images-v1',
  fonts: 'lmr-fonts-v1',
  api: 'lmr-api-v1',
  navigation: 'lmr-navigation-v1',
  runtime: 'lmr-runtime-v2'
};

const API_CACHE_CONFIG = {
  maxEntries: 80,
  maxAgeSeconds: 5 * 60 // 5 minutes
};

// ═══════════════════════════════════════════════════════════════════════════
// Install — Fetch precache-manifest.json and populate the precache
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('install', event => {
  console.log('[SW] Installing — precaching build assets');

  event.waitUntil(
    (async () => {
      try {
        const cache = await caches.open(CACHE_NAMES.precache);
        const manifestResp = await fetch('/precache-manifest.json');

        if (manifestResp.ok) {
          const manifest = await manifestResp.json();

          console.log(`[SW] Precaching ${manifest.length} assets...`);

          // Individual fetch + put instead of atomic addAll
          // This way, a single flaky asset doesn't block the entire precache
          let cached = 0;
          let failed = 0;

          await Promise.allSettled(
            manifest.map(async entry => {
              try {
                const response = await fetch(entry.url, { credentials: 'same-origin' });
                if (response.ok) {
                  await cache.put(entry.url, response);
                  cached++;
                } else {
                  failed++;
                }
              } catch {
                failed++;
              }
            })
          );

          console.log(`[SW] Precaching complete: ${cached} cached, ${failed} failed`);
        } else {
          console.warn('[SW] Could not fetch precache-manifest.json, skipping precache');
        }
      } catch (err) {
        // Silently fail — app still works with network
        console.warn('[SW] Precache failed (expected on first load):', err);
      }
    })()
  );

  self.skipWaiting();
});

// ═══════════════════════════════════════════════════════════════════════════
// Activate — Clean old caches, claim clients
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('activate', event => {
  console.log('[SW] Activating — cleaning old caches');

  const currentCaches = Object.values(CACHE_NAMES);

  event.waitUntil(
    caches
      .keys()
      .then(cacheNames =>
        Promise.all(
          cacheNames
            .filter(name => !currentCaches.includes(name))
            .map(name => {
              console.log('[SW] Deleting old cache:', name);
              return caches.delete(name);
            })
        )
      )
      .then(() => self.clients.claim())
  );
});

// ═══════════════════════════════════════════════════════════════════════════
// Fetch — Runtime caching strategies
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('fetch', event => {
  const { request } = event;
  const url = new URL(request.url);

  // Only handle GET requests
  if (request.method !== 'GET') return;

  // Skip Server-Sent Events (SSE) connections
  if (url.pathname.includes('/sse') || request.headers.get('Accept') === 'text/event-stream') {
    return;
  }

  // Same-origin only (except fonts and CDN)
  if (url.origin !== self.location.origin) {
    // Google Fonts — stale-while-revalidate
    if (url.href.includes('fonts.googleapis.com') || url.href.includes('fonts.gstatic.com')) {
      event.respondWith(fontsStrategy(event));
      return;
    }
    return;
  }

  const pathname = url.pathname;

  // Don't cache the precache manifest itself
  if (pathname === '/precache-manifest.json') return;

  // ── API calls: Network First, fallback to cache ──────────────────────
  if (pathname.startsWith('/api/')) {
    event.respondWith(apiStrategy(event));
    return;
  }

  // ── Navigation (HTML pages): Network First ───────────────────────────
  if (request.mode === 'navigate') {
    event.respondWith(navigationStrategy(event));
    return;
  }

  // ── Static build assets: Precached Cache First ───────────────────────
  if (pathname.startsWith('/_next/static/')) {
    event.respondWith(precacheStrategy(event));
    return;
  }

  // ── Images: Cache First, separate cache with size management ─────────
  if (isImage(pathname)) {
    event.respondWith(imageStrategy(event));
    return;
  }

  // ── Fonts: Cache First ───────────────────────────────────────────────
  if (isFont(pathname)) {
    event.respondWith(fontsStrategy(event));
    return;
  }

  // ── Other static assets (JS, CSS from public/) ───────────────────────
  if (isStaticAsset(pathname)) {
    event.respondWith(staticAssetStrategy(event));
    return;
  }

  // ── Default: Network First ───────────────────────────────────────────
  event.respondWith(networkFirstWithFallback(event));
});

// ═══════════════════════════════════════════════════════════════════════════
// Strategy implementations
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Precached Cache First — serve from precache, fall back to network.
 * This is the primary strategy for all _next/static/ build assets.
 */
async function precacheStrategy(event) {
  const cached = await caches.match(event.request, {
    cacheName: CACHE_NAMES.precache
  });
  if (cached) return cached;

  // Fallback to runtime cache (e.g., if precache had failed)
  const runtimeCached = await caches.match(event.request);
  if (runtimeCached) return runtimeCached;

  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      // Warm runtime cache for future requests
      const cache = await caches.open(CACHE_NAMES.static);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    return new Response('Offline', { status: 503 });
  }
}

/**
 * Cache First — serve from cache, fall back to network.
 */
async function cacheFirst(event) {
  const cached = await caches.match(event.request);
  if (cached) return cached;

  try {
    const response = await fetch(event.request);
    if ((response.ok && response.status !== 206) || response.type === 'opaqueredirect') {
      const cache = await caches.open(CACHE_NAMES.static);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    return new Response('Offline', { status: 503 });
  }
}

/**
 * Network First — try network, fall back to cache.
 */
async function networkFirstWithFallback(event, cacheName = CACHE_NAMES.runtime) {
  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(cacheName);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(event.request);
    return cached || new Response('Offline', { status: 503 });
  }
}

/**
 * Navigation strategy — Network First, fall back to cached HTML, then offline page.
 */
async function navigationStrategy(event) {
  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(CACHE_NAMES.navigation);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(event.request);
    if (cached) return cached;

    // Fall back to cached root page
    const rootCached = await caches.match('/');
    return rootCached || new Response('Offline', { status: 503 });
  }
}

/**
 * API strategy — Network First with short TTL cache.
 */
async function apiStrategy(event) {
  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(CACHE_NAMES.api);

      // Store with timestamp for TTL validation
      const clone = response.clone();
      const blob = await clone.blob();
      const headers = new Headers(clone.headers);
      headers.append('X-SW-Cache-Timestamp', Date.now().toString());

      const cachedResponse = new Response(blob, {
        status: clone.status,
        statusText: clone.statusText,
        headers
      });

      cache.put(event.request, cachedResponse);
    }
    return response;
  } catch {
    const cached = await caches.match(event.request);
    if (!cached) {
      return new Response(JSON.stringify({ success: false, error: 'Offline' }), {
        status: 503,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    // Check TTL
    const timestamp = cached.headers.get('X-SW-Cache-Timestamp');
    if (timestamp) {
      const age = Date.now() - parseInt(timestamp, 10);
      if (age > API_CACHE_CONFIG.maxAgeSeconds * 1000) {
        // Stale but serve it as fallback
        return cached;
      }
    }

    return cached;
  }
}

/**
 * Image strategy — Cache First with max entries management.
 */
async function imageStrategy(event) {
  const cached = await caches.match(event.request);
  if (cached) return cached;

  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(CACHE_NAMES.images);
      cache.put(event.request, response.clone());

      // Evict old entries if cache exceeds limit
      trimCache(CACHE_NAMES.images, 100);
    }
    return response;
  } catch {
    return new Response('Offline', { status: 503 });
  }
}

/**
 * Fonts strategy — Cache First (fonts rarely change).
 */
async function fontsStrategy(event) {
  const cached = await caches.match(event.request);
  if (cached) return cached;

  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(CACHE_NAMES.fonts);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    return new Response('Offline', { status: 503 });
  }
}

/**
 * Static asset strategy — Cache First for public/ assets.
 */
async function staticAssetStrategy(event) {
  const cached = await caches.match(event.request);
  if (cached) return cached;

  try {
    const response = await fetch(event.request);
    if (response.ok && response.status !== 206) {
      const cache = await caches.open(CACHE_NAMES.static);
      cache.put(event.request, response.clone());
    }
    return response;
  } catch {
    return new Response('Offline', { status: 503 });
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════

function isImage(pathname) {
  return /\.(png|jpg|jpeg|gif|svg|ico|webp|avif)$/i.test(pathname);
}

function isFont(pathname) {
  return /\.(woff|woff2|ttf|eot)$/i.test(pathname);
}

function isStaticAsset(pathname) {
  return /\.(js|css|json|xml|txt)$/i.test(pathname) && !pathname.startsWith('/_next/');
}

/**
 * Trim a cache to keep at most maxEntries items (approximate by deleting oldest).
 */
async function trimCache(cacheName, maxEntries) {
  try {
    const cache = await caches.open(cacheName);
    const keys = await cache.keys();
    if (keys.length > maxEntries) {
      const toDelete = keys.slice(0, keys.length - maxEntries);
      await Promise.all(toDelete.map(request => cache.delete(request)));
    }
  } catch {
    // Silently fail — cache trimming is non-critical
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// Push notifications
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('push', event => {
  if (!event.data) return;

  try {
    const data = event.data.json();
    const options = {
      body: data.body || 'Nueva notificación',
      icon: '/img/system/logo1.png',
      badge: '/favicon.ico',
      vibrate: [100, 50, 100],
      data: {
        url: data.url || '/',
        timestamp: Date.now()
      },
      actions: data.actions || [],
      requireInteraction: data.requireInteraction || false
    };

    event.waitUntil(
      self.registration.showNotification(data.title || 'Las Muñecas de Ramón', options)
    );
  } catch (err) {
    console.error('[SW] Error handling push event:', err);
  }
});

self.addEventListener('notificationclick', event => {
  event.notification.close();

  const url = event.notification.data?.url || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window' }).then(clientList => {
      for (const client of clientList) {
        if (client.url === url && 'focus' in client) {
          return client.focus();
        }
      }
      return self.clients.openWindow(url);
    })
  );
});

// ═══════════════════════════════════════════════════════════════════════════
// Background Sync
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('sync', event => {
  if (event.tag === 'sync-pending-data') {
    event.waitUntil(syncPendingData());
  }
});

async function syncPendingData() {
  console.log('[SW] Background sync: processing pending requests');
}

// ═══════════════════════════════════════════════════════════════════════════
// Message handling
// ═══════════════════════════════════════════════════════════════════════════
self.addEventListener('message', event => {
  if (!event.data) return;

  switch (event.data.type) {
    case 'CLEAR_CACHE':
      event.waitUntil(clearAllCaches());
      break;
    case 'SKIP_WAITING':
      self.skipWaiting();
      break;
    case 'GET_VERSION':
      event.ports[0].postMessage({ version: CACHE_NAMES.precache });
      break;
  }
});

async function clearAllCaches() {
  const cacheNames = await caches.keys();
  return Promise.all(cacheNames.map(name => caches.delete(name)));
}

console.log('[SW] Template loaded — Workbox will inject precache manifest on build');
